\section{contact interaction of composite fermions}

The contact interactions for the production and decay of a 
composite fermions $F$ are:
\begin{eqnarray}
{\mathcal L}^{F}_{\rm CI} = {\mathcal V}_{F} +{\mathcal V}_{F}^\dagger. 
\label{cieF}
\end{eqnarray}
In the case of Eq.~(\ref{bhlql1}) and Table \ref{nuF0+},
\begin{eqnarray}
{\mathcal V}_{\bar U^0} &=& \frac{g_*^2}{\Lambda^2}(\bar U^0_{L} u^a_{R})(\bar u^a_{R}\nu^e_{L}), \quad pp~\rightarrow \bar U^0_{L} \nu^e_{L};\quad p\nu_L~\rightarrow \bar U^0_{L} u^a_{R},
\label{cieFf0+}\\ 
{\mathcal V}_{\bar U^+}&=& \frac{g_*^2}{\Lambda^2}(\bar U^+_{L}u^a_{R})(\bar u^a_{R}e_{L}), \quad pp~\rightarrow \bar U^+_{L}e_{L};\quad ep~\rightarrow \bar U^+_{L}u^a_{R},
\label{cinuFf0+}\\
{\mathcal V}_{\bar D^+} &=& \frac{g_*^2}{\Lambda^2}(\bar D^+_{L}d^a_{R})(\bar d^a_{R}e_{L}),
\quad pp~\rightarrow \bar D^+_{L}e_{L}; \quad ep~\rightarrow \bar D^+_{L}d^a_{R},
\label{cieF0+}\\
{\mathcal V}_{\bar D^0} &=& \frac{g_*^2}{\Lambda^2}(\bar D^0_{L}d^a_{R})(\bar d^a_{R}\nu^e_{L}), \quad pp\rightarrow \bar D^0_{L}\nu^e_{R};\quad p\nu_L\rightarrow \bar D^0_{L}d^a_{R},
\label{cinuF0+}
\end{eqnarray}
and their Hermitian conjugates,
\begin{eqnarray}
{\mathcal V}^\dagger_{U^0} &=& \frac{g_*^2}{\Lambda^2}(\bar u^a_{L} U^0_{R})(\bar \nu^e_{R}u_{La}),\quad U^0_{R}\rightarrow \bar  u^a_{L}(\bar\nu^e_{R} u_{aL}),
\label{dcieFf0+}\\
{\mathcal V}^\dagger_{U^-}&=& \frac{g_*^2}{\Lambda^2}
(\bar u^a_{L}U^-_{R})(\bar e_{R}u^a_{L}),\quad U^-_R\rightarrow\bar u^a_{L}(\bar e_{R}u_{aL}),
\label{dcinuFf0+}\\
{\mathcal V}^\dagger_{D^-} &=& \frac{g_*^2}{\Lambda^2}(\bar d^a_{L}D^-_{R})(\bar e_{R}d^a_{L}),\quad D^-_{R}\rightarrow \bar d^a_L(\bar e_{R}d_{La}),
\label{dcieF0+}\\
{\mathcal V}^\dagger_{D^0} &=& \frac{g_*^2}{\Lambda^2}(\bar d^a_{L}D^0_{R})(\bar \nu^e_{R}d^a_{L}),\quad D^0_{R}\rightarrow \bar d^a_{L}(\bar\nu^e_{R}d_{La}).
\label{dcinuF0+}
\end{eqnarray}
In the case of Eq.~(\ref{bhlql2}) and Table \ref{QF0+},
\begin{eqnarray}
&&{\mathcal V}_{\bar E^{-2/3}_{Lb}} = \frac{g_*^2}{\Lambda^2}(\bar E^{-2/3}_{Lb} e_{R})(\bar e_{R}u_{Lb}); \!\!\!\quad\!\!\! ee~\rightarrow \bar E^{-2/3}_{La} u_{Rb};\!\!\!\quad\!\!\! ep~\rightarrow \bar E^{-2/3}_{La} e_{R};
\label{cieQf0+}\\ 
&&{\mathcal V}_{\bar N^{1/3}_{Lb}}= \frac{g_*^2}{\Lambda^2}(\bar N^{1/3}_{Lb}\nu^e_{R})(\bar \nu^e_{R}d_{Lb}); \quad \bar\nu_R\nu_R~\rightarrow \bar N^{1/3}_{La}d_{Ra}; \quad p\nu_R~\rightarrow \bar N^{1/3}_{La}\nu^e_{R},
\label{cinuQf0+}\\
&&{\mathcal V}_{\bar E^{1/3}_{Lb}} = \frac{g_*^2}{\Lambda^2}(\bar E^{1/3}_{Lb}e_{R})(\bar e_{R}d_{Lb});
\quad ee~\rightarrow \bar E^{1/3}_{Lb}d_{Lb};
\quad ep~\rightarrow \bar E^{1/3}_{Lb}e_{R},
\label{cieQ0+}\\
&&{\mathcal V}_{\bar N^{-2/3}_{Lb}} = \frac{g_*^2}{\Lambda^2}(\bar N^{-2/3}_{Lb}\nu^e_{R})(\bar \nu^e_{R}u_{Lb}); \!\!\!\quad\!\!\!
\bar\nu_R\nu_R~\rightarrow \bar N^{-2/3}_{Lb}u_{Rb}; \!\!\!\quad\!\!\!
\bar\nu_Rp~\rightarrow \bar N^{-2/3}_{Lb}\nu^e_{R},
\label{cinuQ0+}
\end{eqnarray}
and their Hermitian conjugates,
\begin{eqnarray}
\!\!&&{\mathcal V}^\dagger_{E^{2/3}_{Rb}} \!=\! \frac{g_*^2}{\Lambda^2}(\bar e_LE^{2/3}_{Rb})(\bar u^b_{R} e_{L}); \!\!\quad\!\!
E^{2/3}_{Rb}\rightarrow \bar  e_{L}(\bar u^b_{R} e_{L}),
\label{dcieQf0+}\\
\!\!\!&&{\mathcal V}^\dagger_{N^{-1/3}_{Rb}}\! = \!\frac{g_*^2}{\Lambda^2}
(\bar\nu^e_{L}N^{-1/3}_{Rb})(\bar d^b_{R}\nu^e_{L});\!\!\!\quad\!\!\! N^{-1/3}_{Rb}\!\!\rightarrow\!\bar\nu^e_{L}(\bar d^b_{R}\nu^e_{L}),
\label{dcinuQf0+}\\
\!\!\!&&{\mathcal V}^\dagger_{E^{-1/3}_{Rb}}\! = \!\frac{g_*^2}{\Lambda^2}(\bar e_{L}E^{-1/3}_{Rb})(\bar d^b_{R}e_{L});
\!\!\!\quad\!\!\! E^{-1/3}_{Rb}\!\!\rightarrow\! \bar e_{L}(\bar d^b_{R}e_{L}),
\label{dcieQ0+}\\
\!\!&&{\mathcal V}^\dagger_{N^{2/3}_{Rb}} \!=\! \frac{g_*^2}{\Lambda^2}(\bar\nu^e_{L}N^{2/3}_{Rb})(\bar u^b_{R}\nu^e_{L});\!\!\quad\!\!
N^{2/3}_{Rb}\rightarrow \bar\nu^e_{L}(\bar u^b_{R}\nu^e_{L}).
\label{dcinuQ0+}
\end{eqnarray}
These are relevant contact interactions for phenomenological studies of possible inelastic channels of composite-fermion production and decay in  $pp$ or $ep$ collisions.


\subsection{Contact interaction of $\Pi^{0,\pm}$ composite boson and gauge bosons}\label{spgg}

However, we shall consider other decay channels at the next leading order, such as neutral composite boson decay to two SM gauge bosons $\Pi^0_{u,d}\rightarrow \tilde G + \tilde G'$. We need a figure for $\Pi \rightarrow \tilde G + \tilde G'$. 
Note that the discussions here in this section do not apply to LQ composite bosons $\Pi^Q_a$ at this leading order, because that SM gauge bosons are zero or integer electric charges and the fractionally charged LQ composite bosons cannot decay to SM gauge bosons. \red{
